export function searchEmojis(query: string): string[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];

  const scored: { emoji: string; score: number }[] = [];

  for (const emoji of ALL_EMOJIS) {
    if (emoji.includes(q)) {
      scored.push({ emoji, score: 100 });
      continue;
    }

    const words = EMOJI_KEYWORDS[emoji];
    if (!words) continue;

    let bestScore = 0;
    for (const w of words) {
      if (w === q) {
        bestScore = Math.max(bestScore, 50);
      } else if (w.startsWith(q)) {
        bestScore = Math.max(bestScore, 30);
      } else if (q.length >= 3 && w.includes(q)) {
        bestScore = Math.max(bestScore, 10);
      }
    }

    if (bestScore > 0) {
      scored.push({ emoji, score: bestScore });
    }
  }

  scored.sort((a, b) => b.score - a.score);
  return scored.map((s) => s.emoji);
}
